"""Opening and closing synthesis for the second experiment volume."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parent


def read(name):
    return json.loads((ROOT / name).read_text(encoding="utf8"))


def cover(w):
    grades = read("repair/grading/summary.json")["arms"]
    times = read("time_read/results.json")
    w.p("Для новой ошибки агент ищет прежнюю работу в том же проекте. Мы проверили, какие части старой записи помогают поиску, когда стоит показывать детали и был ли выбранный опыт вообще доступен к моменту обращения пользователя.")
    w.tbl(["Вопрос", "Наблюдение"], [
        ["Что сохранять", "В статической библиотеке для 85/99 запросов гибридный поиск нашёл связанную историю в первой пятёрке со сведениями о правках, для 81/99 — без них. Все четыре дополнительных попадания переместились с позиции 6 или 7."],
        ["Что читать", "Показ подробностей по фиксированному правилу сохранил 75/99 решений читателя и сократил ввод на 2,46%. Одно случайное правило с той же частотой набрало 76/99."],
        ["Как записывать исход проверки", "Оболочка сообщила успех во всех 20 командах с pytest. В 18 при воспроизведении сам pytest вернул ошибку. Получив измеренный сигнал, Qwen верно записал 20/20 исходов, с обычным журналом — 17/20. Простое правило по сигналу также дало 20/20."],
        ["Когда был доступен опыт", "Ранее влитая размеченная правка нашлась у 17/99 задач Lite и 38/258 остальных. Из 75 исходных попаданий к открытию запроса были доступны 13. После фильтрации кандидатов гибрид с Qwen дал 16/99, вариант с частотами только по прошлым данным — 15/99."],
        ["Что исправил агент", f"Оценщик принял {grades['brief']['resolved']}/4 патчей с краткой памятью, {grades['eager']['resolved']}/4 при немедленном показе деталей и {grades['on_demand']['resolved']}/4 при доступе по запросу. Все сессии исчерпали 24 хода. Пустые патчи были отклонены до запуска тестов."],
        ["Что передать следующей сессии", "На 80 отложенных попытках Qwen→Qwen правило по этапу передачи и полный журнал дали по 38 решений. Вход преемника был на 27% меньше, чем с полным журналом, и на 14% больше, чем с краткой запиской. Интервал разности успеха с полным журналом от −3,49 до +3,75 п. п."]
    ], [4.0,13.1], True)
    w.p(f"Отдельный прогон на всех 99 запросах Lite использовал только ранее влитые исправления. В нём {times['costs']['empty']} запросов имели пустую библиотеку и {times['costs']['singleton']} — ровно одну подходящую по времени запись. Авторы SWE-ContextBench намеренно включили пары с общим PR, а MemDev-Bench уже описала ограничения хронологии. Здесь для фиксированного релиза подсчитаны доступные связи, проверены фактические решения нашего читателя и 380 опубликованных исходов другого эксперимента.", "Caption")
    w.p("Авторы REM сообщили 68 попаданий первой историей и 78 попаданий в пятёрку в статическом режиме. В предыдущем отчёте наш читатель получил 75/99 при зачёте любой связи и 73/99 при зачёте последней. Официальное число REM, наша репликация поиска и новый исторический режим имеют отдельные строки сравнения. Доказательство лидерства по ремонту программ потребовало бы одинаковых решателя, доступа к памяти, бюджета и полного теста.")
    w.source("REM, таблица 1 и приложение D", "https://arxiv.org/html/2610.27377v1")
    w.source("SWE-ContextBench, постановка и исходный эксперимент", "https://arxiv.org/abs/2602.08316")
    w.source("MemDev-Bench, сопоставление с временным протоколом в приложении A", "https://arxiv.org/html/2610.27524v1#A1")


def interpret(w):
    w.page("Вопросы для следующей работы", "Какой результат мог бы изменить выбор метода",
           "Наблюдения позволяют сформулировать четыре эксперимента. Для каждого заранее можно определить, какой исход даст основание развивать подход дальше.")
    w.h("1. Сохранять наблюдение, которое можно ещё раз проверить")
    w.p("В 18 из 20 команд с pytest ненулевой код самого тестового процесса скрыла последующая команда конвейера. Сохранять рабочую ревизию, команду, статус тестового процесса и результат выполнения конкретных тестов. На следующей задаче извлекать запись по совпадению симптома и затронутой области. Сравнить наблюдения об исполнении, пути правок и краткий итог прежней задачи при одинаковом объёме памяти и одном решателе.")
    w.h("2. Определить, когда подробности окупаются")
    w.p("Правило поиска по идентификаторам сократило ввод, но нейтральное по частоте назначение иногда дало лучший результат. В новом опыте агенту можно открывать детальный журнал после воспроизводимой ошибки теста или повторного неудачного поиска. На тех же задачах нужны режимы с краткой записью, полным журналом и случайным открытием при той же частоте. Основные исходы — исправления по скрытым тестам, токены, время и число раскрытий.")
    w.h("3. Составить набор задач с подтверждённым прошлым")
    w.p("Для 302 из 357 обращений опубликованные связи не дали подтверждённого предшествующего источника по принятому правилу. Другие старые исправления могли быть полезны. Для сравнения методов собирать задачи с документированным временем каждого события, архивировать предъявленное issue на этот момент, выделять достаточно случаев с несколькими сопоставимыми кандидатами. Наборы разработчика и итоговой проверки разделить по репозиторию и времени, единицей независимости считать целевой PR.")
    w.h("4. Выбирать форму передачи по тому, кто продолжит работу")
    w.p("На первых попытках Handoff Debt простое правило по получателю оказалось перспективнее варианта, дополнительно учитывавшего предшественника и стадию. Отложенная проверка на одной паре моделей показала, что экономия относительно сырых действий возможна и при равном числе решений. Дальше нужно установить допустимое снижение успеха заранее, сравнить с лучшей постоянной запиской и полным журналом на новых проектах и других получателях. В затраты включить формирование и чтение записки.")
    w.h("Условия решения о публикации")
    w.p("Кандидатом в статью считать метод, который на закрытых задачах воспроизводимо улучшает долю исправлений при том же решателе и сопоставимых затратах либо сохраняет её в заранее выбранном допуске с меньшими затратами. Зафиксировать допустимую потерю качества, правило выбора результата, число повторов и размер выборки до просмотра итогов. Время записи учитывать отдельно. Пары сравнивать на одних и тех же PR, интервалы пересчитывать по репозиториям. Числа по найденным историям и по исполненным патчам сохранять раздельно.")

